-- Candidate bounded historical DATA for paged shared replay. Existing immutable
-- provider semantics retained: current host/admission must hold, while revoked
-- historical origins still explain COMMITTED effects. No new roles/memberships
-- or online table grants. Requires existing Captain and CB history proposals.
begin;
grant create on schema world_v2 to world_v2_day_one_fx_history_owner,world_v2_captain_source_owner;
create function world_v2.read_postwar_paged_omo_originals(p_world text,p_host_country text,p_office text,p_seed text,p_admission text,p_version text,p_sequence text,p_from_version bigint,p_from_sequence bigint,p_through_version bigint,p_through_sequence bigint)
returns table(world_version text,event_sequence text,seed_fingerprint text,admission_ref text,originals jsonb)
language plpgsql security definer set search_path=pg_catalog as $$
declare effective name;required name;h world_v2.world_head%rowtype;a world_v2.runtime_opening_admission%rowtype;permit world_v2.runtime_admission_publication_permit%rowtype;
 host text;origin world_v2.central_bank_omo_adoption%rowtype;stored world_v2.central_bank_omo_original%rowtype;packets jsonb:='[]'::jsonb;quotes jsonb;refs jsonb;n bigint;bytes bigint:=0;parties bigint;begin
 if p_office is null or p_office not in('SOCIAL','FINANCE')then raise exception 'PAGED_ORIGINALS_FIXED_HOST_REQUIRED'using errcode='42501';end if;
 effective:=case when current_setting('role')='none'then session_user else current_setting('role')::name end;
 required:=case p_office when 'FINANCE'then 'world_v2_finance_budget_source_reader'when 'SOCIAL'then 'world_v2_social_source_reader'when 'TREASURY_FX'then 'world_v2_day_one_fx_source_reader'when 'CAPTAIN'then 'world_v2_captain_source_reader'when 'CB_OMO'then 'world_v2_cb_omo_source_reader'when 'TRADE'then 'world_v2_postwar_narrow_trade_source'else null end;
 if required is null or to_regrole(required)is null or not pg_has_role(effective,required,'MEMBER')or exists(select 1 from pg_roles r where r.rolname=effective and(r.rolsuper or r.rolbypassrls or r.rolcreaterole or r.rolcreatedb or r.rolreplication))or exists(select 1 from pg_roles r where r.rolname in('world_v2_day_one_fx_history_owner','world_v2_cb_omo_source_owner','world_v2_cb_omo_source_publisher','world_v2_finance_budget_source_owner','world_v2_finance_budget_source_publisher','world_v2_social_source_owner','world_v2_social_source_publisher','world_v2_day_one_fx_source_owner','world_v2_day_one_fx_source_publisher','world_v2_captain_source_owner')and pg_has_role(effective,r.oid,'MEMBER'))then raise exception 'CB_OMO_HISTORY_FIXED_HOST_READER_REQUIRED'using errcode='42501';end if;
 if p_world is null or p_host_country is null or p_world!~'^[A-Z][A-Z0-9]*([_-][A-Z0-9]+)*$'or p_host_country!~'^[A-Z][A-Z0-9]*([_-][A-Z0-9]+)*$'or p_version is null or p_sequence is null or p_version!~'^(0|[1-9][0-9]*)$'or p_sequence!~'^(0|[1-9][0-9]*)$'then raise exception 'CB_OMO_HISTORY_EXACT_SCOPE_REQUIRED'using errcode='22023';end if;
 perform set_config('econmind.fx_history_world',p_world,true);
 select * into h from world_v2.world_head x where x.world_id=p_world for share;
 if not found or h.world_version::text<>p_version or h.event_sequence::text<>p_sequence then raise exception 'CB_OMO_HISTORY_EXACT_BOUNDED_HEAD_REQUIRED'using errcode='55000';end if;

 if current_setting('transaction_isolation')not in('repeatable read','serializable')or current_setting('transaction_read_only')<>'off'then raise exception 'PAGED_ORIGINALS_HELD_TRANSACTION_REQUIRED'using errcode='25001';end if;
 if p_from_version is null or p_from_sequence is null or p_through_version is null or p_through_sequence is null or p_from_version<0 or p_from_sequence<0 or p_through_version<p_from_version or p_through_sequence<p_from_sequence or p_through_version>h.world_version or p_through_sequence>h.event_sequence or p_through_version-p_from_version>256 or p_through_sequence-p_from_sequence>256 or(p_through_version=p_from_version and h.world_version<>0)then raise exception 'PAGED_ORIGINALS_BOUNDED_INTERVAL_REQUIRED'using errcode='22023';end if;
 if(p_from_version=0 and p_from_sequence<>0)or(p_from_version>0 and not exists(select 1 from world_v2.command_receipt r where r.world_id=p_world and r.outcome='COMMITTED'and r.world_version_after=p_from_version and(select max(e.event_sequence)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=r.command_id)=p_from_sequence))or(p_through_version=0 and p_through_sequence<>0)or(p_through_version>0 and not exists(select 1 from world_v2.command_receipt r where r.world_id=p_world and r.outcome='COMMITTED'and r.world_version_after=p_through_version and(select max(e.event_sequence)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=r.command_id)=p_through_sequence))or(select count(*)from world_v2.command_receipt r where r.world_id=p_world and r.outcome='COMMITTED'and r.world_version_after>p_from_version and r.world_version_after<=p_through_version)<>p_through_version-p_from_version or(select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.event_sequence>p_from_sequence and e.event_sequence<=p_through_sequence and e.world_version>p_from_version and e.world_version<=p_through_version)<>p_through_sequence-p_from_sequence then raise exception 'PAGED_ORIGINALS_COMPLETE_TRANSACTION_BOUNDARIES_REQUIRED'using errcode='55000';end if;
 select * into a from world_v2.runtime_opening_admission x where x.world_id=p_world and x.seed_fingerprint=p_seed and x.admission_ref=p_admission for share;
 if not found or not exists(select 1 from world_v2.opening_seed s where s.world_id=p_world and s.seed_id=a.seed_id and s.seed_fingerprint=p_seed and s.replay_binding=a.replay_binding and s.replay_binding::jsonb->>'modelVersion'=a.model_version)then raise exception 'CB_OMO_HISTORY_ACTUAL_IMMUTABLE_ADMISSION_REQUIRED'using errcode='55000';end if;
 select * into permit from world_v2.runtime_admission_publication_permit x where x.world_id=p_world and x.seed_id=a.seed_id and x.seed_fingerprint=p_seed and x.model_version=a.model_version and x.replay_binding=a.replay_binding and 'ADMISSION_'||upper(x.authorization_sha256)=p_admission and a.admitted_at_real>=x.valid_from and a.admitted_at_real<x.valid_until for share;
 if not found or exists(select 1 from world_v2.runtime_admission_publication_revocation x where x.authorization_id=permit.authorization_id)then raise exception 'CB_OMO_HISTORY_WORLD_ADMISSION_REVOKED'using errcode='55000';end if;
 -- These are current HOST source guards, not delegated Central Bank authority.
 if p_office='TRADE'then
  perform world_v2.assert_postwar_narrow_trade_history_host(p_world,p_host_country,p_seed,p_admission,h.world_version::text,h.event_sequence::text);
  host:='HELD_TRADE_SOURCE_NOT_AUTHORITY';
 elsif p_office='FINANCE'then
  select x.policy_ref into host from world_v2.finance_budget_policy_original x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and not exists(select 1 from world_v2.finance_budget_policy_revocation r where r.policy_ref=x.policy_ref)order by x.policy_ref limit 1 for share;
 elsif p_office='SOCIAL'then
  select x.registration_ref into host from world_v2.social_operating_source_registration x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and not exists(select 1 from world_v2.social_operating_source_revocation r where r.registration_ref=x.registration_ref)for share;
 elsif p_office='TREASURY_FX'then
  select x.registration_ref into host from world_v2.postwar_day_one_fx_source_original x where x.world_id=p_world and x.seed_id=a.seed_id and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and not exists(select 1 from world_v2.postwar_day_one_fx_source_revocation r where r.registration_ref=x.registration_ref)and exists(select 1 from world_v2.postwar_day_one_fx_quote_original q where q.world_id=p_world and q.country_id=p_host_country and not exists(select 1 from world_v2.postwar_day_one_fx_quote_revocation r where r.world_id=q.world_id and r.country_id=q.country_id and r.quote_ref=q.quote_ref))for share;
 elsif p_office='CAPTAIN'then
  select x.adoption_ref into host from world_v2.captain_operating_source_adoption x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_seed and not exists(select 1 from world_v2.captain_operating_source_revocation r where r.adoption_ref=x.adoption_ref)and exists(select 1 from world_v2.captain_source_publication_registry r where r.adoption_ref=x.adoption_ref and r.world_id=p_world and r.seed_fingerprint=p_seed and r.world_admission_ref=p_admission)for share;
 else
  select x.adoption_ref into host from world_v2.central_bank_omo_adoption x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and not exists(select 1 from world_v2.central_bank_omo_revocation r where r.adoption_ref=x.adoption_ref and r.resource_ref='SOURCE')and exists(select 1 from world_v2.central_bank_omo_original o where o.adoption_ref=x.adoption_ref)for share;
 end if;
 if not found then raise exception 'CB_OMO_HISTORY_CURRENT_HOST_SOURCE_REQUIRED'using errcode='55000';end if;
 -- The entire frame prefix is separately processed by the shared Core replay.
 -- This provider neither classifies foreign frames as no-effect nor drops them.
 if(select count(*)from world_v2.authoritative_event e where e.world_id=p_world)<>h.event_sequence or(select count(*)from world_v2.command_receipt r where r.world_id=p_world and r.outcome='COMMITTED')<>h.world_version then raise exception 'CB_OMO_HISTORY_COMPLETE_WORLD_FRONTIER_REQUIRED'using errcode='55000';end if;
 if exists(select 1 from world_v2.command_submission c join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where r.world_version_after>p_from_version and r.world_version_after<=p_through_version and c.world_id=p_world and c.command_type='CORE_CENTRAL_BANK_OMO_V1'and((select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=c.command_id and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1')<>1 or(select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=c.command_id)<>1 or(select count(*)from world_v2.financial_posting_batch b where b.world_id=p_world and b.causation_command_id=c.command_id)<>1 or exists(select 1 from world_v2.inventory_posting i where i.world_id=p_world and i.causation_command_id=c.command_id)))then raise exception 'CB_OMO_HISTORY_COMPLETE_CB_EFFECT_REQUIRED'using errcode='55000';end if;
 if exists(select 1 from world_v2.authoritative_event e where e.world_id=p_world and e.world_version>p_from_version and e.world_version<=p_through_version and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'and octet_length(e.canonical_payload)>65536)then raise exception 'CB_OMO_HISTORY_EVENT_CAPACITY_EXCEEDED'using errcode='54000';end if;
 select count(distinct c.country_id)into parties from world_v2.command_submission c join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where r.world_version_after>p_from_version and r.world_version_after<=p_through_version and c.world_id=p_world and c.command_type='CORE_CENTRAL_BANK_OMO_V1';
 if parties>70 then raise exception 'CB_OMO_HISTORY_COUNTRY_CAPACITY_EXCEEDED'using errcode='54000';end if;
 for origin in select x.* from world_v2.central_bank_omo_adoption x where x.world_id=p_world and x.seed_id=a.seed_id and x.seed_fingerprint=p_seed and x.admission_ref=p_admission and exists(select 1 from world_v2.command_submission c join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where r.world_version_after>p_from_version and r.world_version_after<=p_through_version and c.world_id=p_world and c.country_id=x.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1')order by x.country_id for share loop
  -- Revoked CB originals/quotes still explain historical COMMITTED payments.
  -- The adopted parent is held FOR SHARE. Every child INSERT takes its
  -- conflicting FOR UPDATE lock, and child mutation/truncation is forbidden.
  -- No UPDATE grant on immutable original bytes is needed for this read.
  select * into stored from world_v2.central_bank_omo_original x where x.adoption_ref=origin.adoption_ref;
  if not found or stored.original_sha256<>origin.original_sha256 then raise exception 'CB_OMO_HISTORY_REGISTERED_ORIGIN_REQUIRED'using errcode='55000';end if;
  if exists(select 1 from world_v2.authoritative_event e join world_v2.command_submission c on c.world_id=e.world_id and c.command_id=e.causation_command_id join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where r.world_version_after>p_from_version and r.world_version_after<=p_through_version and e.world_id=p_world and c.country_id=origin.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1'and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'and(e.canonical_payload::jsonb#>>'{trace,snapshot,lineageRef}'is distinct from origin.adoption_ref or e.canonical_payload::jsonb#>>'{trace,snapshot,snapshotRef}'is distinct from origin.source_ref))then raise exception 'CB_OMO_HISTORY_RECORDED_ADOPTION_DIFFERS'using errcode='55000';end if;
  select count(*),coalesce(sum(octet_length(q.quote_text)),0)into n,bytes from world_v2.central_bank_omo_quote q where q.adoption_ref=origin.adoption_ref and exists(select 1 from world_v2.authoritative_event e join world_v2.command_submission c on c.world_id=e.world_id and c.command_id=e.causation_command_id join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where r.world_version_after>p_from_version and r.world_version_after<=p_through_version and e.world_id=p_world and c.country_id=origin.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1'and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'and e.canonical_payload::jsonb#>>'{source,quote,quoteRef}'=q.quote_ref);
  if n>256 or bytes+octet_length(stored.original_text)>1048576 then raise exception 'CB_OMO_HISTORY_ORIGIN_CAPACITY_EXCEEDED'using errcode='54000';end if;
  select coalesce(jsonb_agg(jsonb_build_object('quote_text',q.quote_text,'quote_sha256',q.quote_sha256)order by q.quote_ref),'[]'::jsonb)into quotes from world_v2.central_bank_omo_quote q where q.adoption_ref=origin.adoption_ref and exists(select 1 from world_v2.authoritative_event e join world_v2.command_submission c on c.world_id=e.world_id and c.command_id=e.causation_command_id join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'where r.world_version_after>p_from_version and r.world_version_after<=p_through_version and e.world_id=p_world and c.country_id=origin.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1'and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'and e.canonical_payload::jsonb#>>'{source,quote,quoteRef}'=q.quote_ref);
  select coalesce(jsonb_agg(jsonb_build_object('command_id',c.command_id,'command_fingerprint',c.command_fingerprint,'event_id',e.event_id,'event_fingerprint',e.event_fingerprint,'transition_id',r.transition_id,'financial_batch_fingerprint',b.batch_fingerprint)order by e.event_sequence),'[]'::jsonb)into refs from world_v2.command_submission c join world_v2.command_receipt r on r.world_id=c.world_id and r.command_id=c.command_id and r.outcome='COMMITTED'join world_v2.authoritative_event e on e.world_id=c.world_id and e.causation_command_id=c.command_id and e.event_type='CENTRAL_BANK_OMO_SETTLED_V1'join world_v2.financial_posting_batch b on b.world_id=c.world_id and b.causation_command_id=c.command_id where r.world_version_after>p_from_version and r.world_version_after<=p_through_version and c.world_id=p_world and c.country_id=origin.country_id and c.command_type='CORE_CENTRAL_BANK_OMO_V1';
  packets:=packets||jsonb_build_array(jsonb_build_object('country_id',origin.country_id,'adoption_ref',origin.adoption_ref,'source_class',origin.source_class,'source_ref',origin.source_ref,'source_revision',origin.source_revision,'admission_revision',origin.admission_revision,'original_text',stored.original_text,'original_sha256',stored.original_sha256,'quotes',quotes,'frames',refs));
  if octet_length(packets::text)>1048576 then raise exception 'CB_OMO_HISTORY_TOTAL_CAPACITY_EXCEEDED'using errcode='54000';end if;
 end loop;
 if jsonb_array_length(packets)<>parties then raise exception 'CB_OMO_HISTORY_ALL_PARTICIPATING_ORIGINS_REQUIRED'using errcode='55000';end if;
 return query select h.world_version::text,h.event_sequence::text,p_seed,p_admission,packets;
end;$$;
create function world_v2.read_postwar_paged_captain_originals(p_world text,p_host_country text,p_office text,p_fp text,p_admission text,p_expected text,p_sequence text,p_from_version bigint,p_from_sequence bigint,p_through_version bigint,p_through_sequence bigint)
returns table(world_version text,event_sequence text,seed_fingerprint text,admission_ref text,captain_packets jsonb,host_original_status text)
language plpgsql security definer set search_path=pg_catalog as $$
declare effective name;required name;h record;a world_v2.runtime_opening_admission%rowtype;host text;host_adoption text;host_registry record;n bigint;b bigint;packets jsonb;begin
 if p_office is null or p_office not in('SOCIAL','FINANCE')then raise exception 'PAGED_ORIGINALS_FIXED_HOST_REQUIRED'using errcode='42501';end if;
 effective:=case when current_setting('role')='none'then session_user else current_setting('role')::name end;
 required:=case p_office when 'SOCIAL'then 'world_v2_social_source_reader'when 'FINANCE'then 'world_v2_finance_budget_source_reader'when 'TREASURY_FX'then 'world_v2_day_one_fx_source_reader'when 'CB_OMO'then 'world_v2_cb_omo_source_reader'when 'TRADE'then 'world_v2_postwar_narrow_trade_source'else null end;
 if required is null or(case when p_office='TRADE'then not pg_has_role(effective,required,'MEMBER')else effective<>required end)or exists(select 1 from pg_roles x where x.rolname=session_user and(x.rolsuper or x.rolbypassrls or x.rolcreatedb or x.rolcreaterole or x.rolreplication))or pg_has_role(session_user,'world_v2_captain_source_owner','MEMBER')or(p_office='CB_OMO'and exists(select 1 from pg_roles x where x.rolname in('world_v2_cb_omo_source_owner','world_v2_cb_omo_source_publisher')and pg_has_role(session_user,x.oid,'MEMBER')))then raise exception 'CAPTAIN_HISTORY_FIXED_HOST_READER_REQUIRED'using errcode='42501';end if;
 if p_world is null or p_world!~'^[A-Z][A-Z0-9]*([_-][A-Z0-9]+)*$'or p_sequence is null or p_sequence!~'^(0|[1-9][0-9]*)$'or p_host_country is null or p_host_country!~'^COUNTRY_(0[1-9]|[1-6][0-9]|70)$'or p_expected is null or p_expected!~'^(0|[1-9][0-9]*)$'then raise exception 'CAPTAIN_HISTORY_EXACT_SCOPE_REQUIRED'using errcode='22023';end if;
 perform set_config('econmind.captain_world',p_world,true);
 select x.world_version,x.event_sequence into h from world_v2.world_head x where x.world_id=p_world for share;
 if not found or h.world_version::text<>p_expected or h.event_sequence::text<>p_sequence then raise exception 'CAPTAIN_HISTORY_ACTUAL_BOUNDED_HEAD_REQUIRED'using errcode='55000';end if;

 if current_setting('transaction_isolation')not in('repeatable read','serializable')or current_setting('transaction_read_only')<>'off'then raise exception 'PAGED_ORIGINALS_HELD_TRANSACTION_REQUIRED'using errcode='25001';end if;
 if p_from_version is null or p_from_sequence is null or p_through_version is null or p_through_sequence is null or p_from_version<0 or p_from_sequence<0 or p_through_version<p_from_version or p_through_sequence<p_from_sequence or p_through_version>h.world_version or p_through_sequence>h.event_sequence or p_through_version-p_from_version>256 or p_through_sequence-p_from_sequence>256 or(p_through_version=p_from_version and h.world_version<>0)then raise exception 'PAGED_ORIGINALS_BOUNDED_INTERVAL_REQUIRED'using errcode='22023';end if;
 if(p_from_version=0 and p_from_sequence<>0)or(p_from_version>0 and not exists(select 1 from world_v2.command_receipt r where r.world_id=p_world and r.outcome='COMMITTED'and r.world_version_after=p_from_version and(select max(e.event_sequence)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=r.command_id)=p_from_sequence))or(p_through_version=0 and p_through_sequence<>0)or(p_through_version>0 and not exists(select 1 from world_v2.command_receipt r where r.world_id=p_world and r.outcome='COMMITTED'and r.world_version_after=p_through_version and(select max(e.event_sequence)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=r.command_id)=p_through_sequence))or(select count(*)from world_v2.command_receipt r where r.world_id=p_world and r.outcome='COMMITTED'and r.world_version_after>p_from_version and r.world_version_after<=p_through_version)<>p_through_version-p_from_version or(select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.event_sequence>p_from_sequence and e.event_sequence<=p_through_sequence and e.world_version>p_from_version and e.world_version<=p_through_version)<>p_through_sequence-p_from_sequence then raise exception 'PAGED_ORIGINALS_COMPLETE_TRANSACTION_BOUNDARIES_REQUIRED'using errcode='55000';end if;
 select * into a from world_v2.runtime_opening_admission x where x.world_id=p_world and x.seed_fingerprint=p_fp and x.admission_ref=p_admission;
 if not found then raise exception 'CAPTAIN_HISTORY_ADMISSION_REQUIRED'using errcode='55000';end if;
 perform world_v2.captain_publication_admission(p_world,a.seed_id,p_fp,p_admission);
 if p_office='TRADE'then
  perform world_v2.assert_postwar_narrow_trade_history_host(p_world,p_host_country,p_fp,p_admission,h.world_version::text,h.event_sequence::text);
  host:='HELD_TRADE_SOURCE_NOT_AUTHORITY';
 elsif p_office='SOCIAL'then
  select x.registration_ref into host from world_v2.social_operating_source_registration x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_fp and x.admission_ref=p_admission for share;
  if not found or exists(select 1 from world_v2.social_operating_source_revocation x where x.registration_ref=host)then raise exception 'CAPTAIN_HISTORY_CURRENT_HOST_SOURCE_REQUIRED'using errcode='55000';end if;
 elsif p_office='CB_OMO'then
  if to_regclass('world_v2.central_bank_omo_adoption')is null or to_regclass('world_v2.central_bank_omo_revocation')is null or to_regclass('world_v2.central_bank_omo_original')is null then raise exception 'CAPTAIN_HISTORY_CURRENT_HOST_SOURCE_REQUIRED'using errcode='55000';end if;
  select x.adoption_ref into host from world_v2.central_bank_omo_adoption x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_fp and x.admission_ref=p_admission and exists(select 1 from world_v2.central_bank_omo_original o where o.adoption_ref=x.adoption_ref)for share;
  if not found or exists(select 1 from world_v2.central_bank_omo_revocation x where x.adoption_ref=host and x.resource_ref='SOURCE')then raise exception 'CAPTAIN_HISTORY_CURRENT_HOST_SOURCE_REQUIRED'using errcode='55000';end if;
 elsif p_office='FINANCE'then
  select x.policy_ref into host from world_v2.finance_budget_policy_original x where x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_fp and x.admission_ref=p_admission and not exists(select 1 from world_v2.finance_budget_policy_revocation r where r.policy_ref=x.policy_ref)order by x.policy_ref limit 1 for share;
  if not found then raise exception 'CAPTAIN_HISTORY_CURRENT_HOST_SOURCE_REQUIRED'using errcode='55000';end if;
 else
  select x.registration_ref into host from world_v2.postwar_day_one_fx_source_original x where x.world_id=p_world and x.seed_id=a.seed_id and x.seed_fingerprint=p_fp and x.admission_ref=p_admission for share;
  if not found or exists(select 1 from world_v2.postwar_day_one_fx_source_revocation x where x.registration_ref=host)or not exists(select 1 from world_v2.postwar_day_one_fx_quote_original q where q.world_id=p_world and q.country_id=p_host_country and not exists(select 1 from world_v2.postwar_day_one_fx_quote_revocation r where r.world_id=q.world_id and r.country_id=q.country_id))then raise exception 'CAPTAIN_HISTORY_CURRENT_HOST_SOURCE_REQUIRED'using errcode='55000';end if;
 end if;
 -- Presence is an actual custody lookup, never an exception fallback.
 select x.* into host_registry from world_v2.captain_source_publication_registry x where x.world_id=p_world and x.country_id=p_host_country;
 if not found then
  if exists(select 1 from world_v2.captain_operating_source_adoption x where x.world_id=p_world and x.country_id=p_host_country)then raise exception 'CAPTAIN_CURRENT_EXACT_REGISTRY_REQUIRED'using errcode='55000';end if;
  host_original_status:='NO_REGISTERED_CAPTAIN_ORIGINAL';
 else
  if host_registry.seed_fingerprint is distinct from p_fp or host_registry.world_admission_ref is distinct from p_admission then raise exception 'CAPTAIN_CURRENT_REGISTERED_SEED_MISMATCH'using errcode='55000';end if;
  select x.adoption_ref into host_adoption from world_v2.captain_operating_source_adoption x where x.adoption_ref=host_registry.adoption_ref and x.world_id=p_world and x.country_id=p_host_country and x.seed_fingerprint=p_fp;
  if not found then raise exception 'CAPTAIN_CURRENT_REGISTERED_BUT_NOT_PUBLISHED'using errcode='55000';end if;
  host_original_status:=case when exists(select 1 from world_v2.captain_operating_source_revocation x where x.adoption_ref=host_adoption)then'REVOKED'else'PRESENT'end;
 end if;
 -- History stays valid after Captain adoption revocation; only previously
 -- COMMITTED frames need these exact immutable origins. Current Captain reads
 -- still require their unrevoked source, and cannot use this history entry.
 select count(*),coalesce(sum(octet_length(x.packet_text)),0)into n,b from world_v2.captain_source_publication_registry x where x.world_id=p_world and(x.country_id=p_host_country or exists(select 1 from world_v2.command_submission c join world_v2.command_receipt cr on cr.world_id=c.world_id and cr.command_id=c.command_id and cr.outcome='COMMITTED'where cr.world_version_after>p_from_version and cr.world_version_after<=p_through_version and c.world_id=p_world and c.country_id=x.country_id and c.command_type='CAPTAIN_POLITICAL_CAPITAL_ALLOCATE_V1'));
 if n>70 or b>1048576 then raise exception 'CAPTAIN_HISTORY_BOUNDED_PACKETS_REQUIRED'using errcode='54000';end if;
 select coalesce(jsonb_agg(jsonb_build_object('packet_text',x.packet_text,'packet_sha256',x.packet_sha256,'originals',(select jsonb_object_agg(o.fact_ref,o.original_text)from world_v2.captain_operating_original o where o.adoption_ref=x.adoption_ref))order by x.country_id),'[]'::jsonb)into packets from world_v2.captain_source_publication_registry x where x.world_id=p_world and x.seed_fingerprint=p_fp and x.world_admission_ref=p_admission and(x.country_id=p_host_country or exists(select 1 from world_v2.command_submission c join world_v2.command_receipt cr on cr.world_id=c.world_id and cr.command_id=c.command_id and cr.outcome='COMMITTED'where cr.world_version_after>p_from_version and cr.world_version_after<=p_through_version and c.world_id=p_world and c.country_id=x.country_id and c.command_type='CAPTAIN_POLITICAL_CAPITAL_ALLOCATE_V1'));
 if octet_length(packets::text)>1048576 then raise exception 'CAPTAIN_PAGED_TOTAL_BYTES_EXCEEDED'using errcode='54000';end if;
 return query select h.world_version::text,h.event_sequence::text,p_fp,p_admission,packets,host_original_status;
end;$$;
alter function world_v2.read_postwar_paged_omo_originals(text,text,text,text,text,text,text,bigint,bigint,bigint,bigint) owner to world_v2_day_one_fx_history_owner;
revoke all on function world_v2.read_postwar_paged_omo_originals(text,text,text,text,text,text,text,bigint,bigint,bigint,bigint) from public;
grant execute on function world_v2.read_postwar_paged_omo_originals(text,text,text,text,text,text,text,bigint,bigint,bigint,bigint) to world_v2_social_source_reader,world_v2_finance_budget_source_reader;
alter function world_v2.read_postwar_paged_captain_originals(text,text,text,text,text,text,text,bigint,bigint,bigint,bigint) owner to world_v2_captain_source_owner;
revoke all on function world_v2.read_postwar_paged_captain_originals(text,text,text,text,text,text,text,bigint,bigint,bigint,bigint) from public;
grant execute on function world_v2.read_postwar_paged_captain_originals(text,text,text,text,text,text,text,bigint,bigint,bigint,bigint) to world_v2_social_source_reader,world_v2_finance_budget_source_reader;
revoke create on schema world_v2 from world_v2_day_one_fx_history_owner,world_v2_captain_source_owner;
commit;
